#!/usr/bin/env python3
"""Underline all headlines in the unpacked quarterly_report.docx OOXML content.

Headlines are identified as non-empty paragraphs whose text contains at least
one letter and no lowercase letters (all-caps section titles like
"EXECUTIVE SUMMARY"). Each headline's runs get <w:u w:val="single"/> added to
their run properties. Uses the docx skill Document library when available,
otherwise falls back to plain DOM editing of word/document.xml.
"""
import os
import sys

UNPACKED = sys.argv[1] if len(sys.argv) > 1 else "unpacked"
DOC_PATH = os.path.join(UNPACKED, "word", "document.xml")

LIB = False
try:
    sys.path.insert(0, ".codex/skills/docx")
    from scripts.document import Document
    LIB = True
except Exception:
    pass


def paragraph_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild and t.firstChild.nodeValue:
            parts.append(t.firstChild.nodeValue)
    return "".join(parts)


def is_headline(text):
    s = text.strip()
    if not s:
        return False
    has_letter = any(c.isalpha() for c in s)
    has_lower = any(c.islower() for c in s)
    return has_letter and not has_lower


def add_underline(p, dom):
    for r in p.getElementsByTagName("w:r"):
        rprs = r.getElementsByTagName("w:rPr")
        rpr = rprs[0] if rprs else None
        if rpr is None:
            rpr = dom.createElement("w:rPr")
            r.insertBefore(rpr, r.firstChild)
        if not rpr.getElementsByTagName("w:u"):
            u = dom.createElement("w:u")
            u.setAttribute("w:val", "single")
            rpr.appendChild(u)


headlines = []

if LIB:
    doc = Document(UNPACKED)
    editor = doc["word/document.xml"]
    dom = editor.dom
    for p in dom.getElementsByTagName("w:p"):
        text = paragraph_text(p)
        if is_headline(text):
            add_underline(p, dom)
            headlines.append(text)
    doc.save()
else:
    try:
        from defusedxml import minidom
    except ImportError:
        from xml.dom import minidom
    dom = minidom.parse(DOC_PATH)
    for p in dom.getElementsByTagName("w:p"):
        text = paragraph_text(p)
        if is_headline(text):
            add_underline(p, dom)
            headlines.append(text)
    with open(DOC_PATH, "w", encoding="ascii") as f:
        dom.writexml(f, addindent="  ", newl="\n")

print("Underlined %d headlines:" % len(headlines))
for h in headlines:
    print(" -", h)

#!/usr/bin/env python3
"""Underline all headline paragraphs in unpacked quarterly_report.docx.

Headlines are the all-caps section title lines (e.g. "EXECUTIVE SUMMARY",
"FINANCIAL HIGHLIGHTS", ...). Each headline paragraph is a single run whose
run properties get <w:u w:val="single"/> added, preserving all other content.
"""
import sys, os

SKILL_ROOT = os.path.join(os.getcwd(), '.codex', 'skills', 'docx')
sys.path.insert(0, SKILL_ROOT)
from scripts.document import Document

unpacked = sys.argv[1] if len(sys.argv) > 1 else 'unpacked'
doc = Document(unpacked)
editor = doc['word/document.xml']
dom = editor.dom

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'


def paragraph_text(p):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        if t.firstChild:
            parts.append(t.firstChild.nodeValue)
    return ''.join(parts)


def is_headline(txt):
    letters = [c for c in txt if c.isalpha()]
    if not letters or len(txt) > 80:
        return False
    return all(c.isupper() for c in letters)


# Elements that must precede <w:u> inside <w:rPr> per OOXML schema order.
BEFORE_U = ('w:szCs', 'w:sz', 'w:highlight', 'w:position', 'w:kern', 'w:w',
            'w:spacing', 'w:color', 'w:webHidden', 'w:vanish', 'w:snapToGrid',
            'w:noProof', 'w:imprint', 'w:emboss', 'w:outline', 'w:dstrike',
            'w:strike', 'w:smallCaps', 'w:caps', 'w:iCs', 'w:i', 'w:bCs',
            'w:b', 'w:rFonts', 'w:rStyle')

headline_count = 0
run_count = 0

for p in dom.getElementsByTagName('w:p'):
    if not is_headline(paragraph_text(p)):
        continue
    headline_count += 1
    for r in p.getElementsByTagName('w:r'):
        rPrs = r.getElementsByTagName('w:rPr')
        if rPrs:
            rPr = rPrs[0]
        else:
            rPr = dom.createElementNS(W, 'w:rPr')
            first = r.firstChild
            if first is not None:
                r.insertBefore(rPr, first)
            else:
                r.appendChild(rPr)
        # Remove any existing underline directive on this run.
        for u in rPr.getElementsByTagName('w:u'):
            rPr.removeChild(u)
        u = dom.createElementNS(W, 'w:u')
        u.setAttribute('w:val', 'single')
        anchor = None
        for tag in BEFORE_U:
            found = rPr.getElementsByTagName(tag)
            if found:
                anchor = found[-1]
        if anchor is not None:
            nxt = anchor.nextSibling
            if nxt is not None:
                rPr.insertBefore(u, nxt)
            else:
                rPr.appendChild(u)
        else:
            rPr.appendChild(u)
        run_count += 1

print(f'Headlines underlined: {headline_count}; runs updated: {run_count}')
doc.save()
print('Saved edited OOXML back to unpacked directory.')

